INSERT INTO outcome_measures (code, name, specialty, domain, scale_type, min_value, max_value, unit, higher_is_better, per_side, sub_items, frequency, instructions, licence_note) VALUES
 ('NPRS', 'Pain - Numeric Pain Rating Scale', 'all', 'pain', 'numeric', 0, 10, 'points', false, false, NULL, 'every_session', 'Ask the patient to rate their pain now: 0 = no pain, 10 = worst imaginable.', 'Free for clinical use'),
 ('PSFS', 'Patient-Specific Functional Scale (up to 3 activities)', 'all', 'function', 'numeric', 0, 10, 'points', true, false, '["Activity 1","Activity 2","Activity 3"]'::jsonb, 'every_session', 'The patient names up to 3 activities they find difficult and rates each 0 (unable) to 10 (as before).', 'Free for clinical use'),
 ('GAS', 'Goal Attainment Scaling (per goal)', 'all', 'goal', 'ordinal', -2, 2, 'points', true, false, NULL, 'review', '-2 much less than expected, -1 less, 0 expected, +1 more, +2 much more than expected.', 'Free for clinical use'),
 ('PGIC', 'Patient Global Impression of Change', 'all', 'global', 'ordinal', 1, 7, 'points', false, false, NULL, 'review', '1 = very much improved ... 4 = no change ... 7 = very much worse. Lower is better.', 'Free for clinical use'),
 ('MMT', 'Manual Muscle Testing - Oxford scale (per muscle group)', 'physio', 'strength', 'ordinal', 0, 5, 'grade', true, true, NULL, 'review', 'Oxford grade 0-5 for the named muscle group.', 'Free for clinical use'),
 ('MAS', 'Modified Ashworth Scale - spasticity (per muscle group)', 'physio-neuro', 'tone', 'ordinal', 0, 4, 'grade', false, true, NULL, 'review', 'Grade 0, 1, 1+, 2, 3, 4. Enter 1+ as 1.5.', 'Free for clinical use'),
 ('ROM', 'Range of motion (per joint/movement)', 'physio', 'mobility', 'degrees', 0, 360, 'degrees', true, true, NULL, 'review', 'Goniometer reading in degrees for the named joint and movement.', 'Free for clinical use'),
 ('FMA_UE', 'Fugl-Meyer Assessment - upper extremity motor', 'physio-neuro / OT', 'motor', 'numeric', 0, 66, 'points', true, true, NULL, 'review', 'Total motor score of the upper extremity, 0-66.', 'Free for clinical use'),
 ('FMA_LE', 'Fugl-Meyer Assessment - lower extremity motor', 'physio-neuro', 'motor', 'numeric', 0, 34, 'points', true, true, NULL, 'review', 'Total motor score of the lower extremity, 0-34.', 'Free for clinical use'),
 ('BBS', 'Berg Balance Scale', 'physio-neuro', 'balance', 'numeric', 0, 56, 'points', true, false, NULL, 'review', '14 items scored 0-4, total 0-56.', 'Free for clinical use'),
 ('TUG', 'Timed Up and Go', 'physio', 'mobility', 'time_seconds', 0, NULL, 'seconds', false, false, NULL, 'review', 'Seconds to stand, walk 3 m, turn, return and sit.', 'Free for clinical use'),
 ('10MWT', '10-Metre Walk Test - gait speed', 'physio-neuro', 'gait', 'speed_mps', 0, NULL, 'm/s', true, false, NULL, 'review', '10 m divided by the seconds taken at a comfortable speed.', 'Free for clinical use'),
 ('FAC', 'Functional Ambulation Category', 'physio-neuro', 'gait', 'ordinal', 0, 5, 'grade', true, false, NULL, 'review', '0 non-functional ... 5 independent on any surface.', 'Free for clinical use'),
 ('BI', 'Barthel Index - activities of daily living', 'physio / OT / nursing', 'adl', 'numeric', 0, 100, 'points', true, false, NULL, 'baseline_discharge', 'Total of 10 daily-living items, 0-100.', 'Free for clinical use'),
 ('MRS', 'Modified Rankin Scale', 'neuro', 'disability', 'ordinal', 0, 6, 'grade', false, false, NULL, 'baseline_discharge', '0 no symptoms ... 5 severe disability, 6 dead. Lower is better.', 'Free for clinical use'),
 ('FOIS', 'Functional Oral Intake Scale - swallowing', 'speech', 'swallowing', 'ordinal', 1, 7, 'level', true, false, NULL, 'review', 'Level 1 (nothing by mouth) to 7 (total oral diet, no restrictions).', 'Free for clinical use'),
 ('SPEECH_INT', 'Speech intelligibility - % of words understood by an unfamiliar listener (therapist-rated)', 'speech', 'speech', 'percent', 0, 100, '%', true, false, NULL, 'review', 'Percentage of words an unfamiliar listener understands in a short sample.', 'Free for clinical use'),
 ('NAMING', 'Picture naming accuracy - % correct on Curevan standard 30-picture set', 'speech', 'language', 'percent', 0, 100, '%', true, false, NULL, 'review', 'Show the 30 standard pictures; record the percentage named correctly.', 'Curevan own set'),
 ('COMM_FUNC', 'Functional communication rating (Curevan 0-7 scale)', 'speech', 'communication', 'ordinal', 0, 7, 'level', true, false, NULL, 'every_session', '0 none, 1 yes/no with cues, 2 basic needs with cues, 3 basic needs alone, 4 familiar topics with help, 5 most topics with occasional help, 6 independent in routine settings, 7 independent everywhere.', 'Curevan own scale'),
 ('COMM_CONF', 'Patient/family communication confidence', 'speech', 'communication', 'numeric', 0, 10, 'points', true, false, NULL, 'review', 'Ask the patient or family how confident they feel communicating, 0-10.', 'Free for clinical use')
